// 🔧 Utilidades
function sumarMinutos(fechaStr, minutos) {
  const fecha = new Date(fechaStr);
  if (isNaN(fecha)) throw new Error(`Fecha inválida: ${fechaStr}`);
  fecha.setMinutes(fecha.getMinutes() + minutos);
  const [fechaPart, horaPart] = fecha.toISOString().split("T");
  const horaLocal = horaPart.substring(0, 5);
  return `${fechaPart}T${horaLocal}:00`;
}

function tiempoAHorasMinutos(tiempoStr) {
  const [h, m, s] = (tiempoStr || "0:30:00").split(":").map(Number);
  return (h * 60) + (m || 0);
}

// 🧩 Obtener datos desde nodos
const raw = $("When Executed by Another Workflow").all();
const modelo = $("Code4").first()?.json?.modelo || null;
const tiempos = $("Get_Tiempo").first()?.json || {};
const reglas = $("Get_Reglas").first()?.json || {};

// 🧹 Extraer correctamente los datos
let solicitud;
if (Array.isArray(raw)) {
  const first = raw[0];
  solicitud = first.json?.query ? JSON.parse(first.json.query) : first.json;
} else {
  solicitud = raw.json?.query ? JSON.parse(raw.json.query) : raw;
}

// 🧩 Reconstruir Fecha y Fin si faltan
if (!solicitud.Fin && solicitud.Fecha && solicitud.hora_fin) {
  solicitud.Fin = `${solicitud.Fecha}T${solicitud.hora_fin}:00`;
}
if (!solicitud.hora_inicio && solicitud.Fecha && solicitud.hora_inicio) {
  solicitud.Fecha = `${solicitud.Fecha}T${solicitud.hora_inicio}:00`;
} else if (!solicitud.Fecha.includes("T") && solicitud.hora_inicio) {
  solicitud.Fecha = `${solicitud.Fecha}T${solicitud.hora_inicio}:00`;
}

// 🚨 Validar
if (!solicitud.Fecha || !solicitud.Fin) {
  return [{
    json: {
      error: "Faltan campos requeridos",
      solicitud,
      tieneFecha: !!solicitud.Fecha,
      tieneFin: !!solicitud.Fin,
    },
  }];
}

// 🕐 Calcular tiempos
const tiempoModeloStr = modelo && tiempos[modelo] ? tiempos[modelo] : "0:30:00";
const minutosModelo = tiempoAHorasMinutos(tiempoModeloStr) || 30;

// Nueva hora de inicio (+15 min de recepción)
const nuevaFechaInicio = sumarMinutos(solicitud.Fecha, 15);

// Nuevo fin (+tiempo del modelo)
let nuevoFin = sumarMinutos(nuevaFechaInicio, minutosModelo);

// ✅ Devolver resultado final
return [{
  json: {
    ...solicitud,
    Fecha: nuevaFechaInicio,
    Fin: nuevoFin,
    Modelo: modelo || "Desconocido",
    Tiempo_Modelo: tiempoModeloStr,
    Calendar: reglas.Id_Calendario || "54e76531d432c15df73ed90e6cca47c95605c52085b9f491bb1b0ddac0fd7818@group.calendar.google.com",
    Fallback_Aplicado: !modelo || !tiempos[modelo],
  },
}];

// 🚗 Lista de modelos posibles
const MODELOS = [
  "Etios",
  "Yaris",
  "Yaris GR",
  "Corolla",
  "Prius",
  "Rav4",
  "Innova",
  "Hilux",
  "SW4",
  "Hiace",
  "CH-R",
  "Camry",
  "Land Cruiser"
];

// 🧩 Función para extraer datos del nodo anterior
function extraerDatos(input) {
  let datos;

  // si viene en formato array con .json.query
  if (Array.isArray(input)) {
    const first = input[0];
    if (first.json?.query) {
      datos = typeof first.json.query === "string" ? JSON.parse(first.json.query) : first.json.query;
    } else if (first.json) {
      datos = first.json;
    } else {
      datos = first;
    }
  } else if (input.json?.query) {
    datos = typeof input.json.query === "string" ? JSON.parse(input.json.query) : input.json.query;
  } else if (input.query) {
    datos = typeof input.query === "string" ? JSON.parse(input.query) : input.query;
  } else {
    datos = input;
  }

  return datos;
}

// 🧮 Buscar modelo en texto
function detectarModelo(texto) {
  for (const modelo of MODELOS) {
    const regex = new RegExp(`\\b${modelo}\\b`, "i");
    if (regex.test(texto)) return modelo;
  }
  return null;
}

// 🧮 Buscar kilometraje en texto
function detectarKilometraje(texto) {
  const match = texto.match(/(\d{1,3}(?:\.\d{3})*|\d+)\s*km/i);
  if (match) {
    const km = match[1].replace(/\./g, "");
    return parseInt(km, 10);
  }
  return null;
}

// 🔹 Obtener datos correctamente desde el nodo anterior
const raw = $("When Executed by Another Workflow").all();
const solicitud = extraerDatos(raw);

// 🔍 Buscar modelo y km
const textoBusqueda = `${solicitud.Descripcion || ""} ${solicitud.Titulo || ""}`;
const modeloDetectado = detectarModelo(textoBusqueda);
const kmDetectado = detectarKilometraje(textoBusqueda);

// 🧾 Devolver resultado
return [
  {
    json: {
      modelo: modeloDetectado,
      kilometraje: kmDetectado,
      textoAnalizado: textoBusqueda // 👈 útil para debug
    },
  },
];

